'use client';

/**
 * SpacecraftViewer — real GLB spacecraft studio with local IBL, tier-adaptive
 * rendering, NASA engineering specs, and Android/iOS AR launch paths.
 *
 * The models in `/public/models` are generated by `scripts/build-3d-models.mjs`
 * (GLTFExporter + USDZExporter), so every craft is a genuine 3D asset rather
 * than primitives assembled inside the render tree.
 */

import React, { Suspense, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { ContactShadows, Html, OrbitControls, useGLTF } from '@react-three/drei';
import { Box, ExternalLink, Loader2, RotateCcw, RotateCw, Satellite } from 'lucide-react';
import * as THREE from 'three';
import type { SupportedLanguage } from '../../i18n/translations';
import { useDevicePerformance } from '../../hooks/useDevicePerformance';
import SpaceEnvironment from '../../three/lighting/SpaceEnvironment';
import CinematicPostprocessing from '../../three/postprocessing/CinematicPostprocessing';
import DynamicStarfield from '../DynamicStarfield.jsx';
import { FallbackPlanet, ModelErrorBoundary } from '../FallbackPlanet.jsx';
import {
  getSpacecraftViewerConfig,
  SPACECRAFT_CATALOG,
} from '../../three/spacecraftCatalog';

// Warm the model cache after the viewer mounts so switching craft is instant;
// total payload is ~300 KB of GLB and no network work happens at import.
function usePreloadSpacecraft() {
  useEffect(() => {
    SPACECRAFT_CATALOG.forEach(({ glb }) => useGLTF.preload(glb));
  }, []);
}

function SpacecraftModel({
  url,
  spinning,
  reducedMotion,
  enableShadows,
}: {
  url: string;
  spinning: boolean;
  reducedMotion: boolean;
  enableShadows: boolean;
}) {
  const { scene } = useGLTF(url);
  const root = useRef<THREE.Group>(null);

  // Clone so auto-rotation and shadow flags never mutate the shared GLTF cache.
  const model = useMemo(() => {
    const cloned = scene.clone(true);
    cloned.traverse((obj) => {
      if ((obj as THREE.Mesh).isMesh) {
        const meshObj = obj as THREE.Mesh;
        meshObj.castShadow = enableShadows;
        meshObj.receiveShadow = enableShadows;
      }
    });
    return cloned;
  }, [scene, enableShadows]);

  useFrame((_, rawDelta) => {
    if (spinning && !reducedMotion && root.current) {
      root.current.rotation.y += Math.min(rawDelta, 0.1) * 0.42;
    }
  });

  return (
    <group ref={root}>
      <primitive object={model} />
    </group>
  );
}

function CameraFramingController({
  position,
  resetToken,
  controlsRef,
}: {
  position: readonly [number, number, number];
  resetToken: number;
  controlsRef: React.RefObject<React.ComponentRef<typeof OrbitControls> | null>;
}) {
  const { camera } = useThree();

  useEffect(() => {
    camera.position.set(position[0], position[1], position[2]);
    if (controlsRef.current) {
      controlsRef.current.target.set(0, 0, 0);
      controlsRef.current.update();
    }
  }, [camera, controlsRef, position, resetToken]);

  return null;
}

function sceneViewerUrl(glbPath: string): string {
  const origin = typeof window === 'undefined' ? '' : window.location.origin;
  const file = encodeURIComponent(`${origin}${glbPath}`);
  return `https://arvr.google.com/scene-viewer/ar?file=${file}&mode=ar_only&resizable=false`;
}

const copy = {
  title: { en: 'Spacecraft model archive', si: 'අභ්‍යවකාශ යානා ආකෘති ලේඛනාගාරය', ta: 'விண்கல மாதிரி தொகுப்பு' },
  subtitle: {
    en: 'Real exported GLB / USDZ assets · drag to orbit, scroll to zoom',
    si: 'සත්‍ය GLB / USDZ ආකෘති · කරකැවීමට අදින්න, විශාලනයට අනුචලනය කරන්න',
    ta: 'உண்மையான GLB / USDZ மாதிரிகள் · சுழற்ற இழுக்கவும், பெரிதாக்க உருட்டவும்',
  },
  spin: { en: 'Auto-rotate', si: 'ස්වයං-භ්‍රමණය', ta: 'தானியங்கு சுழற்சி' },
  reset: { en: 'Reset view', si: 'දසුන යළි සකසන්න', ta: 'பார்வையை மீட்டமை' },
  arAndroid: { en: 'View in AR (Android)', si: 'AR තුළ බලන්න (Android)', ta: 'AR-இல் காண்க (Android)' },
  arIos: { en: 'View in AR (iPhone / iPad)', si: 'AR තුළ බලන්න (iPhone / iPad)', ta: 'AR-இல் காண்க (iPhone / iPad)' },
  loading: { en: 'Loading spacecraft model…', si: 'අභ්‍යවකාශ යානා ආකෘතිය පූරණය වෙමින්…', ta: 'விண்கல மாதிரி ஏற்றப்படுகிறது…' },
  ecoNote: {
    en: 'Eco / static inspection mode active — launch Android Scene Viewer or iOS Quick Look below for full-scale AR.',
    si: 'Eco මාදිලිය සක්‍රීයයි — සම්පූර්ණ AR දසුන සඳහා පහත Android හෝ iOS AR බොත්තම් භාවිතා කරන්න.',
    ta: 'Eco பயன்முறை செயலில் உள்ளது — முழு அளவிலான AR பார்வைக்கு கீழே உள்ள Android அல்லது iOS AR பொத்தான்களைப் பயன்படுத்தவும்.',
  },
} as const;

export default function SpacecraftViewer({ lang = 'en' }: { lang?: SupportedLanguage }) {
  usePreloadSpacecraft();
  const [selectedId, setSelectedId] = useState(SPACECRAFT_CATALOG[0].id);
  const [spinning, setSpinning] = useState(true);
  const [resetToken, setResetToken] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);
  const [inView, setInView] = useState(true);
  const [tabVisible, setTabVisible] = useState(true);
  const [contextLost, setContextLost] = useState(false);

  const hostRef = useRef<HTMLDivElement>(null);
  const controlsRef = useRef<React.ComponentRef<typeof OrbitControls> | null>(null);
  const cleanupCanvasRef = useRef<(() => void) | null>(null);

  const { isOptimizedModeActive, supportsWebGL, qualityProfile, gpuTier } = useDevicePerformance();
  const viewerConfig = useMemo(() => getSpacecraftViewerConfig(qualityProfile), [qualityProfile]);
  const selected = SPACECRAFT_CATALOG.find((c) => c.id === selectedId) ?? SPACECRAFT_CATALOG[0];

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return undefined;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => {
      setReducedMotion(mq.matches);
      if (mq.matches) setSpinning(false);
    };
    sync();
    mq.addEventListener?.('change', sync);
    return () => mq.removeEventListener?.('change', sync);
  }, []);

  useEffect(() => {
    const node = hostRef.current;
    if (!node || typeof IntersectionObserver === 'undefined') return undefined;
    const observer = new IntersectionObserver(
      (entries) => setInView(entries.some((e) => e.isIntersecting)),
      { threshold: 0.05 }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const onVis = () => setTabVisible(!document.hidden);
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);

  useEffect(() => {
    return () => {
      cleanupCanvasRef.current?.();
      cleanupCanvasRef.current = null;
    };
  }, []);

  const handleResetView = useCallback(() => {
    setResetToken((n) => n + 1);
  }, []);

  const showCanvas =
    supportsWebGL && viewerConfig.enableWebGL && !isOptimizedModeActive && !contextLost;

  return (
    <div ref={hostRef} className="overflow-hidden rounded-3xl border border-cyan-500/30 bg-abyss">
      {/* Header / model picker */}
      <div className="flex flex-col gap-3 border-b border-white/10 p-4 sm:p-5">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2.5">
            <Satellite className="h-4.5 w-4.5 text-cyan-300" />
            <div>
              <p className="text-sm font-semibold text-ink">{copy.title[lang]}</p>
              <p className="text-[11px] text-ink-3">{copy.subtitle[lang]}</p>
            </div>
          </div>
          <span className="rounded-full border border-cyan-500/30 bg-cyan-500/10 px-2.5 py-0.5 font-mono text-[10px] uppercase text-cyan-300">
            {selected.category} · {gpuTier.toUpperCase()}
          </span>
        </div>

        <div className="flex flex-wrap gap-1.5" role="tablist" aria-label="Spacecraft models">
          {SPACECRAFT_CATALOG.map((craft) => (
            <button
              key={craft.id}
              type="button"
              role="tab"
              aria-selected={craft.id === selectedId}
              onClick={() => setSelectedId(craft.id)}
              className={`rounded-[10px] border px-3 py-1.5 text-[11.5px] font-semibold transition cursor-pointer ${
                craft.id === selectedId
                  ? 'border-cyan-400/60 bg-cyan-500/20 text-cyan-100'
                  : 'border-white/10 bg-white/[0.03] text-ink-2 hover:border-cyan-400/30 hover:text-ink'
              }`}
            >
              {craft.name[lang]}
            </button>
          ))}
        </div>
      </div>

      {/* 3D viewport or Eco/context-lost fallback */}
      <div className="relative h-[420px] sm:h-[520px] bg-[radial-gradient(ellipse_at_50%_45%,rgba(14,44,86,0.34),rgba(3,6,14,0.98)_72%)]">
        {showCanvas ? (
          <Canvas
            frameloop={inView && tabVisible ? 'always' : 'demand'}
            dpr={viewerConfig.dpr}
            shadows={viewerConfig.enableShadows}
            camera={{
              position: [
                selected.cameraPosition[0],
                selected.cameraPosition[1],
                selected.cameraPosition[2],
              ],
              fov: 40,
            }}
            gl={{
              antialias: true,
              alpha: true,
              powerPreference: 'high-performance',
              toneMapping: THREE.ACESFilmicToneMapping,
              toneMappingExposure: 1.15,
            }}
            onCreated={({ gl }) => {
              gl.setClearColor(0x000000, 0);
              cleanupCanvasRef.current?.();
              const dom = gl.domElement;
              const onLost = (e: Event) => {
                e.preventDefault();
                setContextLost(true);
              };
              const onRestored = () => setContextLost(false);
              dom.addEventListener('webglcontextlost', onLost, false);
              dom.addEventListener('webglcontextrestored', onRestored, false);
              cleanupCanvasRef.current = () => {
                dom.removeEventListener('webglcontextlost', onLost, false);
                dom.removeEventListener('webglcontextrestored', onRestored, false);
              };
            }}
          >
            <CameraFramingController
              position={selected.cameraPosition}
              resetToken={resetToken}
              controlsRef={controlsRef}
            />

            {/* Calibrated orbital studio lighting + local procedural IBL reflections */}
            <ambientLight intensity={0.28} />
            <hemisphereLight args={[0xbfe3ff, 0x101829, 0.42]} />
            <directionalLight
              position={[6, 7, 5]}
              intensity={2.4}
              color="#fffaf0"
              castShadow={viewerConfig.enableShadows}
            />
            <directionalLight position={[-6, -3, -4]} intensity={0.62} color="#5ed3f2" />

            <SpaceEnvironment
              intensity={0.72}
              resolution={viewerConfig.environmentResolution}
            />

            <DynamicStarfield
              count={viewerConfig.starCount}
              minRadius={36}
              maxRadius={130}
              driftSpeed={0.003}
              reducedMotion={reducedMotion}
            />

            <ModelErrorBoundary fallback={<FallbackPlanet radius={1.6} color="#38bdf8" wireframe />}>
              <Suspense
                fallback={
                  <Html center>
                    <div className="flex items-center gap-2 whitespace-nowrap rounded-full border border-white/10 bg-abyss/90 px-4 py-2 text-[11.5px] text-ink-2">
                      <Loader2 className="h-3.5 w-3.5 animate-spin text-cyan-300" />
                      {copy.loading[lang]}
                    </div>
                  </Html>
                }
              >
                <SpacecraftModel
                  key={selected.id}
                  url={selected.glb}
                  spinning={spinning}
                  reducedMotion={reducedMotion}
                  enableShadows={viewerConfig.enableShadows}
                />
                {viewerConfig.enableContactShadows && (
                  <ContactShadows
                    frames={1}
                    position={[0, -2.25, 0]}
                    opacity={0.38}
                    scale={9}
                    blur={2.4}
                    far={5}
                    color="#000814"
                  />
                )}
              </Suspense>
            </ModelErrorBoundary>

            <OrbitControls
              ref={controlsRef}
              enablePan={false}
              enableDamping
              dampingFactor={0.07}
              minDistance={2.8}
              maxDistance={10.5}
              maxPolarAngle={Math.PI * 0.88}
            />

            <CinematicPostprocessing
              enabled={viewerConfig.enablePostprocessing}
              bloomIntensity={viewerConfig.bloomIntensity}
              luminanceThreshold={0.88}
              vignetteDarkness={0.42}
            />
          </Canvas>
        ) : (
          <div className="flex h-full flex-col items-center justify-center gap-4 p-6 text-center">
            <div className="flex h-16 w-16 items-center justify-center rounded-2xl border border-cyan-500/35 bg-cyan-500/10 text-cyan-300">
              <Satellite className="h-8 w-8" />
            </div>
            <div className="max-w-md space-y-1.5">
              <p className="font-display text-base font-bold text-ink">{selected.name[lang]}</p>
              <p className="text-xs leading-relaxed text-ink-3">{copy.ecoNote[lang]}</p>
            </div>
            {contextLost && (
              <button
                type="button"
                onClick={() => setContextLost(false)}
                className="rounded-[10px] bg-cyan-600 px-4 py-2 text-xs font-semibold text-white transition hover:bg-cyan-500"
              >
                Restore 3D Viewport
              </button>
            )}
          </div>
        )}

        {/* Viewport toolbar: Reset view + Auto-rotate */}
        {showCanvas && (
          <div className="absolute right-3 top-3 flex items-center gap-1.5">
            <button
              type="button"
              onClick={handleResetView}
              className="flex items-center gap-1.5 rounded-[10px] border border-white/10 bg-abyss/75 px-2.5 py-1.5 text-[11px] font-semibold text-ink-2 transition hover:border-cyan-400/40 hover:text-ink cursor-pointer"
              title={copy.reset[lang]}
            >
              <RotateCcw className="h-3.5 w-3.5 text-cyan-300" />
              <span className="hidden sm:inline">{copy.reset[lang]}</span>
            </button>
            <button
              type="button"
              onClick={() => setSpinning((v) => !v)}
              className={`flex items-center gap-1.5 rounded-[10px] border px-2.5 py-1.5 text-[11px] font-semibold transition cursor-pointer ${
                spinning
                  ? 'border-cyan-400/50 bg-cyan-500/20 text-cyan-100'
                  : 'border-white/10 bg-abyss/75 text-ink-2 hover:text-ink'
              }`}
            >
              <RotateCw className={`h-3.5 w-3.5 ${spinning && !reducedMotion ? 'animate-[spin_3s_linear_infinite]' : ''}`} />
              {copy.spin[lang]}
            </button>
          </div>
        )}

        {/* NASA Engineering Spec Strip */}
        <div className="pointer-events-none absolute bottom-3 left-3 right-3 flex flex-wrap gap-1.5">
          {[
            ['Orbit', selected.specs.orbit],
            ['Launched', selected.specs.launchYear],
            ['Scale', selected.specs.dimensions],
            ['Mass', selected.specs.mass],
          ].map(([label, value]) => (
            <div
              key={label}
              className="rounded-[10px] border border-white/10 bg-abyss/80 px-2.5 py-1 font-mono text-[10.5px]"
            >
              <span className="text-ink-4">{label}: </span>
              <span className="font-semibold text-cyan-200">{value}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Caption + AR actions */}
      <div className="flex flex-col gap-3 border-t border-white/10 p-4 sm:flex-row sm:items-center sm:justify-between sm:p-5">
        <div className="min-w-0">
          <p className="flex items-center gap-2 text-sm font-semibold text-ink">
            <Box className="h-4 w-4 shrink-0 text-cyan-300" />
            {selected.name[lang]}
          </p>
          <p className="mt-1 max-w-xl text-[11.5px] leading-relaxed text-ink-3">{selected.detail[lang]}</p>
        </div>
        <div className="flex shrink-0 flex-wrap gap-2">
          <a
            href={sceneViewerUrl(selected.glb)}
            target="_blank"
            rel="noreferrer noopener"
            className="inline-flex items-center gap-1.5 rounded-[10px] bg-gradient-to-r from-cyan-600 to-blue-600 px-3 py-2 text-[11.5px] font-semibold text-white transition hover:from-cyan-500 hover:to-blue-500"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            {copy.arAndroid[lang]}
          </a>
          {/* iOS Quick Look: Safari intercepts rel="ar" anchors and opens the USDZ. */}
          <a
            href={selected.usdz}
            rel="ar"
            className="inline-flex items-center gap-1.5 rounded-[10px] border border-white/15 bg-white/[0.05] px-3 py-2 text-[11.5px] font-semibold text-ink transition hover:border-cyan-400/40 hover:text-cyan-100"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            {copy.arIos[lang]}
          </a>
        </div>
      </div>
    </div>
  );
}
